sys_script_include.script:
var businessServiceHealthKPI = Class.create();
businessServiceHealthKPI.prototype = {
    initialize: function() {
        this.weights = {
            availability: 0.3,
            performance: 0.3,
            discovery_health: 0.2,
            relationship_health: 0.2
        };
    },
    calculate: function() {
        var bsGr = new GlideRecord('cmdb_ci_service');
        bsGr.addQuery('operational_status', 1);
        bsGr.query();
        var results = {
            services: [],
			sysIds : [],
            overall_health: 0,
            critical_services_count: 0
        };

        while (bsGr.next()) {
            var serviceHealth = this._calculateServiceHealth(bsGr);
			results.sysIds.push(bsGr.getUniqueValue())
            results.services.push(serviceHealth);
            results.overall_health += serviceHealth.health_score;
            if (serviceHealth.criticality === 'high') {
                results.critical_services_count++;
            }
        }
        results.overall_health /= results.services.length || 1;
        return results;
    },
    _calculateServiceHealth: function(service) {
        var availability = this._getAvailabilityScore(service);
        var performance = 90;
        var discoveryHealth = this._getDiscoveryHealth(service);
        var relationshipHealth = this._getRelationshipHealth(service);
        return {
            name: service.getDisplayValue(),
            sys_id: service.sys_id.toString(),
            criticality: service.business_criticality,
            health_score: this._calculateWeightedScore({
                availability: availability,
                performance: performance,
                discovery_health: discoveryHealth,
                relationship_health: relationshipHealth
            }),
            metrics: {
                availability: availability,
                performance: performance,
                discovery_health: discoveryHealth,
                relationship_health: relationshipHealth
            },
            incidents: this._getRecentIncidents(service),
            changes: this._getRecentChanges(service)
        };
    },
    _getAvailabilityScore: function(service) {
        var score = 100;
        var incGr = new GlideRecord('incident');
        incGr.addQuery('cmdb_ci', service.sys_id);
        // incGr.addQuery('state', '!=', 'Closed');
		incGr.addEncodedQuery('state!=7')
        incGr.query();
        while (incGr.next()) {
            score -= 10;
        }
        return Math.max(0, score);
    },
   _getPerformanceScore: function(service) {
    var score = 100;
    var indicatorGr = new GlideRecord('pa_indicators'); // Using the PA indicator table
    indicatorGr.addQuery('cmdb_ci', service.sys_id);
    indicatorGr.query();
    while (indicatorGr.next()) {
        score -= 5; // Deduct 5 points per indicator record found
    }
    return Math.max(0, score);
},

    _getRelationshipHealth: function(service) {
        var score = 100;
        var relGr = new GlideRecord('cmdb_rel_ci');
        relGr.addQuery('parent', service.sys_id);
        relGr.query();
        while (relGr.next()) {
            score -= 5;
        }
        return Math.max(0, score);
    },
    _calculateWeightedScore: function(scores) {
        return (scores.availability * this.weights.availability +
                scores.performance * this.weights.performance +
                scores.discovery_health * this.weights.discovery_health +
                scores.relationship_health * this.weights.relationship_health);
    },
    _getRecentIncidents: function(service) {
        var incidents = [];
        var incGr = new GlideRecord('incident');
        incGr.addQuery('cmdb_ci', service.sys_id);
        // incGr.addQuery('state', '!=', 'Closed');
		incGr.addEncodedQuery('state!=7')
        incGr.query();
        while (incGr.next()) {
            incidents.push({
                number: incGr.number.toString(),
                state: incGr.state.toString(),
                short_description: incGr.short_description.toString()
            });
        }
        return incidents;
    },
    _getRecentChanges: function(service) {
        var changes = [];
        var chgGr = new GlideRecord('change_request');
        chgGr.addQuery('cmdb_ci', service.sys_id);
        // chgGr.addQuery('state', '!=', 'Closed');
		chgGr.addEncodedQuery('state!=7')
        chgGr.query();
        while (chgGr.next()) {
            changes.push({
                number: chgGr.number.toString(),
                state: chgGr.state.toString(),
                short_description: chgGr.short_description.toString()
            });
        }
        return changes;
    },
    _calculateDiscoveryDeductions: function(discoveredGr) {
        return 10; 
    },

	_getDiscoveryHealth: function(service) {
    var score = 100;
    // Query the cmdb_ci_service_discovered table where the discovered record's name
    // matches the business service's name. Adjust this if you have another matching field.
    var discoveredGr = new GlideRecord('cmdb_ci_service_discovered');
    discoveredGr.addQuery('name', service.getValue('name'));
    discoveredGr.query();
    while (discoveredGr.next()) {
        // Deduct points based on the discovered record issue
        score -= this._calculateDiscoveryDeductions(discoveredGr);
    }
    return Math.max(0, score);
},


};
